// ops.js — every change to shared state, as a named operation over a plain
// state object. This file runs in two places with no other dependencies:
//   - the browser (window.AxisOps), where state.js's commit() applies an op
//     locally and hands it to whichever window holds the session socket
//   - the Worker's SessionRoom Durable Object, which applies the same op
//     to the session's document before broadcasting it
// If it isn't in OPS it isn't shared. Ids (members, instances, conditions,
// effects) are generated by the caller and travel in the args, so applying
// an op is deterministic everywhere.
//
// Roles: 'gm' may send anything. 'player' may send the ops in PLAYER_OPS,
// and only against their claimed character, its companions, and their
// tokens — see permits(). playerView() is the document a player socket is
// allowed to see.
(function (root, factory) {
  if (typeof module !== 'undefined' && module.exports) module.exports = factory();
  else root.AxisOps = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  function member(s, id) {
    return (s.party || []).find((m) => m.id === id) || null;
  }

  function combat(s, adventureId, sceneHash) {
    const adv = (s.combat || {})[adventureId] || {};
    return adv[sceneHash] || null;
  }

  function setCombat(s, adventureId, sceneHash, c) {
    if (!s.combat) s.combat = {};
    if (!s.combat[adventureId]) s.combat[adventureId] = {};
    s.combat[adventureId][sceneHash] = c;
  }

  function instance(s, adventureId, sceneHash, instanceId) {
    const c = combat(s, adventureId, sceneHash);
    return c ? (c.instances || []).find((i) => i.instanceId === instanceId) || null : null;
  }

  function companionFor(s, defRef) {
    const i = String(defRef).indexOf(':');
    if (i === -1) return null;
    const m = member(s, defRef.slice(0, i));
    const key = defRef.slice(i + 1);
    const c = m && (m.snapshot.companions || []).find((x) => x.key === key);
    return c ? { member: m, companion: c, key } : null;
  }

  function findTokenInstance(s, sceneHash, instanceId) {
    // tokens are keyed by instanceId; the instance lives under some
    // adventure's combat for this scene
    const advs = s.combat || {};
    for (const a in advs) {
      const c = advs[a][sceneHash];
      const inst = c && (c.instances || []).find((i) => i.instanceId === instanceId);
      if (inst) return inst;
    }
    return null;
  }

  const OPS = {
    // ── party ─────────────────────────────────────────────────────────
    addPartyMember(s, m) {
      if (!s.party) s.party = [];
      if (!s.party.some((x) => x.id === m.id)) s.party.push(m);
    },
    resyncPartyMember(s, id, snapshot) {
      const m = member(s, id);
      if (!m) return;
      m.snapshot = snapshot;
      m.gm.hpCurrent = Math.min(m.gm.hpCurrent, snapshot.hpMax);
    },
    removePartyMember(s, id) {
      s.party = (s.party || []).filter((m) => m.id !== id);
    },
    setPartyHp(s, id, hpCurrent) {
      const m = member(s, id);
      if (m) m.gm.hpCurrent = hpCurrent;
    },
    setPartyNotes(s, id, notes) {
      const m = member(s, id);
      if (m) m.gm.notes = notes;
    },
    setPartyConditions(s, id, conditions) {
      const m = member(s, id);
      if (m) m.gm.conditions = conditions;
    },
    setPartyLive(s, id, patch) {
      const m = member(s, id);
      if (m) Object.assign(m.gm, patch);
    },
    setSlotUsed(s, id, level, used) {
      const m = member(s, id);
      if (m) m.gm.slotsUsed[level] = Math.max(0, used);
    },
    setPactUsed(s, id, used) {
      const m = member(s, id);
      if (m) m.gm.pactUsed = Math.max(0, used);
    },
    setResourceUsed(s, id, key, used) {
      const m = member(s, id);
      if (m) m.gm.resourcesUsed[key] = Math.max(0, used);
    },
    setInventoryQty(s, id, key, quantity) {
      const m = member(s, id);
      if (m) m.gm.inventory[key] = { quantity: Math.max(0, quantity) };
    },
    restParty(s, id, kind) {
      const m = member(s, id);
      if (!m) return;
      (m.snapshot.resources || []).forEach((r) => {
        if (kind === 'long' || r.reset === 'short') m.gm.resourcesUsed[r.key] = 0;
      });
      m.gm.pactUsed = 0;
      if (kind === 'long') {
        m.gm.slotsUsed = {};
        m.gm.hpCurrent = m.snapshot.hpMax;
        m.gm.tempHp = 0;
        m.gm.deathSaves = { success: 0, fail: 0 };
      }
    },

    // ── combat ────────────────────────────────────────────────────────
    setCombatState(s, adventureId, sceneHash, c) {
      setCombat(s, adventureId, sceneHash, c);
    },
    clearCombatState(s, adventureId, sceneHash) {
      if (s.combat && s.combat[adventureId]) delete s.combat[adventureId][sceneHash];
    },
    addCombatInstance(s, adventureId, sceneHash, inst) {
      let c = combat(s, adventureId, sceneHash);
      if (!c) c = { round: 1, turnIndex: 0, instances: [] };
      if (!c.instances) c.instances = [];
      if (!c.instances.some((i) => i.instanceId === inst.instanceId)) c.instances.push(inst);
      setCombat(s, adventureId, sceneHash, c);
    },
    removeCombatInstance(s, adventureId, sceneHash, instanceId) {
      const c = combat(s, adventureId, sceneHash);
      if (!c) return;
      c.instances = (c.instances || []).filter((i) => i.instanceId !== instanceId);
      if (c.turnIndex >= c.instances.length) c.turnIndex = 0;
    },
    setInstanceHp(s, adventureId, sceneHash, instanceId, hpCurrent) {
      const inst = instance(s, adventureId, sceneHash, instanceId);
      if (!inst) return;
      inst.hpCurrent = hpCurrent;
      if (inst.sourceKind === 'party') {
        const m = member(s, inst.defRef);
        if (m) m.gm.hpCurrent = hpCurrent;
      }
      if (inst.sourceKind === 'companion') {
        const c = companionFor(s, inst.defRef);
        if (c) c.member.gm.companionHp[c.key] = hpCurrent;
      }
    },
    setInstanceInitiative(s, adventureId, sceneHash, instanceId, initiative) {
      const inst = instance(s, adventureId, sceneHash, instanceId);
      if (inst) inst.initiative = initiative;
    },
    setInstanceNotes(s, adventureId, sceneHash, instanceId, notes) {
      const inst = instance(s, adventureId, sceneHash, instanceId);
      if (inst) inst.notes = notes;
    },
    addInstanceCondition(s, adventureId, sceneHash, instanceId, cond) {
      const inst = instance(s, adventureId, sceneHash, instanceId);
      if (!inst) return;
      if (!inst.conditions) inst.conditions = [];
      inst.conditions.push(cond);
    },
    removeInstanceCondition(s, adventureId, sceneHash, instanceId, conditionId) {
      const inst = instance(s, adventureId, sceneHash, instanceId);
      if (inst) inst.conditions = (inst.conditions || []).filter((c) => c.id !== conditionId);
    },
    // Advances the round: decrements timed conditions, drops expired ones.
    tickDurations(s, adventureId, sceneHash) {
      const c = combat(s, adventureId, sceneHash);
      if (!c) return;
      (c.instances || []).forEach((inst) => {
        inst.conditions = (inst.conditions || []).filter((cond) => {
          if (cond.duration == null) return true;
          cond.duration -= 1;
          return cond.duration > 0;
        });
      });
    },

    // ── maps ──────────────────────────────────────────────────────────
    setMapState(s, sceneHash, map) {
      if (!s.maps) s.maps = {};
      s.maps[sceneHash] = map;
    },
    setTokenPosition(s, sceneHash, instanceId, x, y) {
      const map = (s.maps || {})[sceneHash];
      const t = map && (map.tokens || []).find((tk) => tk.instanceId === instanceId);
      if (t) {
        t.x = x;
        t.y = y;
      }
    },

    // ── scene the GM is on (the table follows it) ─────────────────────
    setTrackerPage(s, adventureId, pageIndex) {
      if (!s.trackerPage) s.trackerPage = {};
      s.trackerPage[adventureId] = pageIndex;
    },
    // GM's own scene order (array of scene hashes); null restores the
    // source's. Shared so every window pages the same way.
    setSceneOrder(s, adventureId, hashes) {
      if (!s.sceneOrder) s.sceneOrder = {};
      if (hashes) s.sceneOrder[adventureId] = hashes;
      else delete s.sceneOrder[adventureId];
    },
  };

  // ── roles ──────────────────────────────────────────────────────────
  function ownsInstance(s, memberId, inst) {
    if (!inst) return false;
    if (inst.sourceKind === 'party') return inst.defRef === memberId;
    if (inst.sourceKind === 'companion') return inst.owner === memberId;
    return false;
  }

  const LIVE_KEYS = ['hpCurrent', 'tempHp', 'deathSaves', 'inspiration', 'playerNotes', 'conditions'];

  // name -> (state, memberId, args) => boolean
  const PLAYER_OPS = {
    setPartyHp: (s, me, a) => a[0] === me,
    setPartyConditions: (s, me, a) => a[0] === me,
    setPartyLive: (s, me, a) => a[0] === me && Object.keys(a[1] || {}).every((k) => LIVE_KEYS.indexOf(k) !== -1),
    setSlotUsed: (s, me, a) => a[0] === me,
    setPactUsed: (s, me, a) => a[0] === me,
    setResourceUsed: (s, me, a) => a[0] === me,
    setInventoryQty: (s, me, a) => a[0] === me,
    restParty: (s, me, a) => a[0] === me,
    addCombatInstance: (s, me, a) => !!a[2] && a[2].sourceKind === 'companion' && a[2].owner === me,
    setInstanceHp: (s, me, a) => ownsInstance(s, me, instance(s, a[0], a[1], a[2])),
    addInstanceCondition: (s, me, a) => ownsInstance(s, me, instance(s, a[0], a[1], a[2])),
    removeInstanceCondition: (s, me, a) => ownsInstance(s, me, instance(s, a[0], a[1], a[2])),
    setTokenPosition: (s, me, a) => ownsInstance(s, me, findTokenInstance(s, a[0], a[1])),
  };

  function permits(s, role, memberId, name, args) {
    if (!OPS[name]) return false;
    if (role === 'gm') return true;
    if (role !== 'player' || !memberId) return false;
    const rule = PLAYER_OPS[name];
    return !!rule && !!rule(s, memberId, args || []);
  }

  function apply(s, name, args) {
    const fn = OPS[name];
    if (!fn) throw new Error('Unknown op ' + name);
    fn.apply(null, [s].concat(args || []));
  }

  // ── player view ────────────────────────────────────────────────────
  function filterMember(m) {
    const gm = Object.assign({}, m.gm, { notes: '' });
    return Object.assign({}, m, { gm });
  }

  function filterCombat(c) {
    if (!c) return c;
    return Object.assign({}, c, { instances: (c.instances || []).map((i) => Object.assign({}, i, { notes: '' })) });
  }

  function filterMap(map) {
    if (!map) return map;
    return Object.assign({}, map, { tokens: (map.tokens || []).filter((t) => !t.hidden) });
  }

  function playerView(s) {
    const combatOut = {};
    Object.keys(s.combat || {}).forEach((adv) => {
      combatOut[adv] = {};
      Object.keys(s.combat[adv]).forEach((scene) => {
        combatOut[adv][scene] = filterCombat(s.combat[adv][scene]);
      });
    });
    const mapsOut = {};
    Object.keys(s.maps || {}).forEach((scene) => {
      mapsOut[scene] = filterMap(s.maps[scene]);
    });
    return {
      party: (s.party || []).map(filterMember),
      combat: combatOut,
      maps: mapsOut,
      trackerPage: s.trackerPage || {},
      sceneOrder: s.sceneOrder || {},
    };
  }

  // What a player socket receives when this op was applied. Ops on
  // GM-only data come back as null; wholesale ops come back as a filtered
  // replacement so a player never sees a hidden token or a GM note.
  function forPlayers(s, name, args) {
    if (name === 'setPartyNotes' || name === 'setInstanceNotes') return null;
    if (name === 'addPartyMember') return { name, args: [filterMember(args[0])] };
    if (name === 'setCombatState') return { name, args: [args[0], args[1], filterCombat(args[2])] };
    if (name === 'addCombatInstance') return { name, args: [args[0], args[1], args[2], Object.assign({}, args[3], { notes: '' })] };
    if (name === 'setMapState') return { name, args: [args[0], filterMap(args[1])] };
    if (name === 'setTokenPosition') {
      const map = (s.maps || {})[args[0]];
      const t = map && (map.tokens || []).find((tk) => tk.instanceId === args[1]);
      if (t && t.hidden) return null;
    }
    return { name, args };
  }

  // The shared slice of a full client state (what the GM sends to seed a
  // session).
  function sharedSlice(s) {
    return { party: s.party || [], combat: s.combat || {}, maps: s.maps || {}, trackerPage: s.trackerPage || {}, sceneOrder: s.sceneOrder || {} };
  }

  const SHARED_KEYS = ['party', 'combat', 'maps', 'trackerPage', 'sceneOrder'];

  return { OPS, PLAYER_OPS, apply, permits, playerView, forPlayers, sharedSlice, SHARED_KEYS, ownsInstance, companionFor };
});
